library_mount_modal_usb_warn_body: "/mnt/usb* और /mnt/ext* PS5 कर्नेल के USB हॉटप्लग नेमस्पेस का हिस्सा हैं; अधिकांश फ़र्मवेयर पर वहाँ इमेज माउंट करना कर्नेल नीति द्वारा अवरुद्ध है। यदि \"Operation not permitted\" के साथ विफल हो, तो /mnt/ps5upload (पेलोड का निजी माउंट रूट) या /data पर जाएँ — दोनों कर्नेल पैच के बिना काम करते हैं।",
