  upload_auto_resume_hint:
    "अगर अपलोड बीच में टूट जाए — अक्सर PS5 पेलोड क्रैश होने के कारण — तो पेलोड अपने आप दोबारा भेजकर वहीं से अपलोड जारी किया जाता है, हार मानने से पहले कुछ बार कोशिश होती है। PS5 की जगह खत्म होने जैसी गंभीर समस्याएँ अब भी तुरंत रोक देती हैं। डिफ़ॉल्ट रूप से चालू।",
