    "अपलोड चलते समय PS5 का ऑटो-स्टैंडबाय टाइमर समय-समय पर रीसेट किया जाता है ताकि वह ट्रांसफ़र के बीच रेस्ट मोड में न चला जाए (विफल अपलोड का एक आम कारण)। डिफ़ॉल्ट रूप से चालू।",
  bandwidth_cap_label: "अपलोड गति सीमा",
