    "अपलोड {n} MB/s पर सीमित हैं। सीमा हटाने के लिए 0 सेट करें।",
  bandwidth_cap_off_hint:
    "कोई सीमा नहीं। अगर अपलोड आपका Wi-Fi/LAN पूरी तरह घेर लेते हैं और दूसरे डिवाइस धीमे हो जाते हैं, तो एक सीमा लगाएँ — यह अपलोड को थ्रॉटल करके बाकी के लिए जगह छोड़ती है। अगले शुरू होने वाले ट्रांसफ़र पर लागू होती है।",
  reset_hint:
    "PS5Upload का हर स्थानीय निशान मिटाकर नए सिरे से शुरू करें: सेटिंग्स, सहेजे गए PS5, गतिविधि/कतार इतिहास, पेलोड कैश और क्रैश रिपोर्ट। आपके PS5 पर कुछ भी प्रभावित नहीं होता। अगर बाद में ज़रूरत पड़ सकती है, तो पहले ऊपर से बैकअप निर्यात करें।",
  reset_action: "सभी सेटिंग्स और डेटा रीसेट करें",
  reset_confirm_title: "PS5Upload रीसेट करें?",
  reset_confirm_body:
    "यह PS5Upload का सारा स्थानीय डेटा स्थायी रूप से हटा देता है — सेटिंग्स, आपके सहेजे गए PS5, गतिविधि/कतार इतिहास, पेलोड कैश और क्रैश रिपोर्ट। यह आपके PS5 पर किसी चीज़ को नहीं छूता। ऐप नई अवस्था में फिर लोड होता है। इसे पूर्ववत नहीं किया जा सकता।",
