upload_split_pick_entry_body: "यह विभाजित सेट का एक वॉल्यूम है, पूरा आर्काइव नहीं। ऊपर बताई गई फ़ाइल चुनें — बाकी वॉल्यूम अपने-आप पढ़ लिए जाते हैं, उन्हें अलग से अपलोड करने की ज़रूरत नहीं।",
upload_split_unsupported_title: "यह एक विभाजित आर्काइव ({count} वॉल्यूम) है जिसे ps5upload नहीं खोल सकता",
upload_split_unsupported_body: "इसे अपलोड करने पर कच्चा वॉल्यूम ही आपके PS5 पर चला जाता है, जिसे वह इस्तेमाल नहीं कर सकता। पहले वॉल्यूम को एक आर्काइव में जोड़ें: 7-Zip या WinRAR से पहला वॉल्यूम खोलकर निकालें, फिर निकाला हुआ फ़ोल्डर या उसका एक ही आर्काइव अपलोड करें।",
