helper_mismatch_body: "नए संस्करण के सुधार और सुविधाएँ तब तक काम नहीं करेंगी जब तक कंसोल का हेल्पर मेल न खाए। कनेक्शन स्क्रीन से इसे फिर से लोड करें।",
