"pack_mismatch_body": "फ़ोल्डर {pack} बताता है, लेकिन आप {target} में इंस्टॉल कर रहे हैं। इंस्टॉल करने पर इस गेम का eboot उस गेम के eboot से बदल जाएगा।",
