"power_action_wake_signin": "चालू करें और साइन इन करें",
"power_action_wake_signin_busy": "चालू और साइन इन हो रहा है…",
"power_wake_signin_setup_hint": "सामान्य वेक उपयोगकर्ता-चयन पर रुक जाता है। आपके कंसोल की दो सत्र कुंजियों (रजिस्ट्रेशन कुंजी और RP-Key, दोनों 32 हेक्स अक्षर) के साथ, वेक आपके उपयोगकर्ता में भी साइन इन कर देता है। Chiaki उपयोगकर्ताओं के पास दोनों पंजीकृत कंसोल सेटिंग्स में होती हैं।",
