"connection_prior_killed": "पिछला हेल्पर ठीक से बंद नहीं हुआ",
"connection_prior_killed_detail": "इसका मतलब हो सकता है कि कंसोल पर किसी दूसरे payload ने उसे बंद कर दिया, सिस्टम की मेमोरी कम पड़ गई, या वह क्रैश हो गया। बग रिपोर्ट में मौजूद stderr.log बताता है कि कौन-सा कारण था। अगर आप ps5upload को ऑटोलोडर से लोड करते हैं, तो इसके बजाय इसे यहाँ से भेजकर देखें।",
"connection_elfldr_first": "क्या आप ps5upload को ऑटोलोडर या PLDMGR से लोड कर रहे हैं? उसकी सूची में elfldr को सबसे पहले, ps5upload.elf से पहले रखें। elfldr पहले लोड न होने पर ps5upload जुड़ता है और कुछ ही सेकंड में कट जाता है।",
