"games_ready_description": "इस PS5 पर रजिस्टर्ड गेम। इन्हें यहाँ से चलाएँ, रोकें, जाँचें या अनइंस्टॉल करें।",
"games_files_description": "कंसोल स्टोरेज में मिले गेम फ़ोल्डर और डिस्क इमेज। सोर्स फ़ाइलों को यहाँ माउंट, रजिस्टर, स्थानांतरित या जाँचें।",
"update_channel_prerelease_label": "प्री-रिलीज़ संस्करण पाएँ",
"update_channel_prerelease_hint": "नए रिलीज़ प्रकाशित होते ही, असली हार्डवेयर पर जाँचे जाने से पहले ही देता है। केवल सत्यापित रिलीज़ पाने के लिए इसे बंद रखें।",
"pkglib.badge.pkgWarning": "पैकेज जाँचें",
"pkglib.fpkgsupport.title": "नकली पैकेज (FPKG) इंस्टॉल कर रहे हैं?",
"pkglib.fpkgsupport.lead": "PS5 नकली पैकेज तभी इंस्टॉल होता है जब कंसोल पर नकली-पैकेज सपोर्ट पहले से लोड हो। इंस्टॉल करने से पहले तीनों को इसी क्रम में लोड करें:",
"pkglib.fpkgsupport.kstuff": "— PS5 नकली-पैकेज सपोर्ट वाला संस्करण",
"pkglib.fpkgsupport.ppr": "— PPR प्लेनटेक्स्ट / बिना-प्रमाणीकरण पैच लगाता है",
"pkglib.fpkgsupport.smp": "— माउंट परत जो इंस्टॉल हुए टाइटल को रजिस्टर करती है",
"pkglib.fpkgsupport.tail": "इनके बिना कंसोल इंस्टॉल अस्वीकार कर देता है, या स्वीकार करके फिर गेम माउंट नहीं कर पाता। रिटेल और डीबग पैकेज को इनमें से कुछ नहीं चाहिए — अगर आप वही इंस्टॉल कर रहे हैं तो इस नोट को अनदेखा करें।",
"fpkg_title": "FPKG में बदलें",
"fpkg.subtitle": "किसी गेम फ़ोल्डर या माउंट इमेज को इंस्टॉल करने योग्य पैकेज में बदलें। काम इसी मशीन पर चलता है, कंसोल पर नहीं।",
