"fpkg.languageAll": "जैसा गेम आता है (सभी भाषाएँ)",
"fpkg.languageHint": "अधिकांश गेम कंसोल की भाषा का पालन करते हैं। केवल उस गेम के लिए एक चुनें जो दूसरी भाषा पर सेट कंसोल पर भी अंग्रेज़ी में रहता है: तब पैकेज गेम को बताता है कि वही भाषा इंस्टॉल है। गेम में वह भाषा होनी चाहिए।",
