"pkg.reason.stalled": "PS5 ने पूरा होने से पहले पैकेज लाना बंद कर दिया। पैकेज रखा गया है — दोबारा कोशिश करें।",
"pkg.reason.stream_unreachable": "पैकेज लाने के लिए PS5 इस कंप्यूटर तक कभी नहीं पहुँच पाया। इस कंप्यूटर के फ़ायरवॉल में ps5upload को अनुमति दें (Windows पर निजी और सार्वजनिक दोनों नेटवर्क के लिए), कंप्यूटर और PS5 को बिना VPN के एक ही नेटवर्क पर रखें, और PS5 का प्रॉक्सी सर्वर “उपयोग न करें” पर सेट करें। अपलोड करें और इंस्टॉल करें इस कनेक्शन के बिना काम करता है।",
"pkg.reason.stream_proxy": "PS5 की प्रॉक्सी सेटिंग ने स्ट्रीम रोक दी। PS5 की नेटवर्क उन्नत सेटिंग में प्रॉक्सी सर्वर को “उपयोग न करें” पर सेट करें, या अपलोड करें और इंस्टॉल करें का उपयोग करें, जो पैकेज को PS5 के लोकल स्टोरेज से पढ़ता है।",
