"fpkg.about": "किसी गेम फ़ोल्डर, या .exfat या .ffpkg माउंट इमेज को चुनें। कनवर्टर ट्री पढ़ता है, जाँचता है कि चलने योग्य पैकेज के लिए सब कुछ मौजूद है, और आउटपुट फ़ोल्डर में डीबग-फ़ॉर्मेट .pkg लिखता है।",
"fpkg.aboutWhere": "बदलने का काम इंजन चलाने वाली मशीन पर होता है — यह कंप्यूटर, कोई Docker होस्ट या Android डिवाइस — कंसोल पर नहीं। जब तक आप पैकेज इंस्टॉल नहीं करते, कंसोल तक कुछ नहीं पहुँचता — इस कंप्यूटर से स्ट्रीम करके, या पहले PS5 पर अपलोड करके।",
"fpkg.aboutSource": "सोर्स पहले से डिक्रिप्ट किया हुआ गेम ट्री होना चाहिए। रिटेल इंस्टॉल को यहाँ खोला नहीं जा सकता, और अगर आपने वही चुना है तो नीचे की जाँच बता देगी।",
"fpkg.aboutFake": "नतीजा एक नकली पैकेज है, इसलिए इंस्टॉल से पहले कंसोल पर नकली-पैकेज सपोर्ट लोड होना चाहिए: kstuff (PS5 नकली-पैकेज सपोर्ट वाला संस्करण), a53_ppr_install_fast.elf और shadowmountplus.elf, इसी क्रम में। पैकेज इंस्टॉल करें स्क्रीन भी अपने इंस्टॉल बटन के पास यही बताती है।",
"fpkg.aboutChecks": "जाँच क्या देखती है",
"fpkg.checkEboot": "ट्री की जड़ में एक eboot.bin — टाइटल मॉड्यूल। यह कच्चा ELF या लपेटा हुआ SELF होना चाहिए; रिटेल-साइन मॉड्यूल को दोबारा पैक नहीं किया जा सकता।",
"fpkg.checkParam": "sce_sys/param.json हो, और sce_sys/param.sfo न हो — param.sfo कंसोल के लॉन्च पथ को PS4 वाले रास्ते पर भेज देता है।",
"fpkg.checkIcons": "36 अक्षरों का कंटेंट आईडी, दोनों आइकन, और अधिकार मॉड्यूल sce_sys/about/right.sprx।",
"fpkg.checkDrm": "कि पैकेज का DRM मान मानक है। मुफ़्त या अपग्रेड-योग्य मान से कंसोल टाइटल को लॉक कर देता है; इसे केवल पैकेज में दोबारा लिखा जाता है, आपकी अपनी फ़ाइल को कभी नहीं छुआ जाता।",
"payloads_essentials_title": "ps5upload के साथ सुझाए गए",
"payloads_essentials_body": "अगर आप पहली बार कंसोल सेट कर रहे हैं, तो ये तीन वह सब कवर करते हैं जिसकी ps5upload को ज़्यादातर ज़रूरत होती है: kstuff-lite (ज़्यादातर होमब्रू जिन कर्नेल पैच पर निर्भर है), ShadowMount+ (स्टोरेज से गेम इमेज माउंट करना) और nanoDNS (कंसोल को Sony के अपडेट रास्ते से दूर रखना)। इस सूची में बाकी सब वैकल्पिक है।",
"payloads_tab_shadowmount": "ShadowMount+",
"payloads_tab_nanodns": "nanoDNS",
"payloads_description_shadowmount": "चुने गए PS5 पर ShadowMount+ की स्थिति, माउंट की गई गेम इमेज, कॉन्फ़िगरेशन और डायग्नोस्टिक्स देखें।",
"payloads_description_nanodns": "nanoDNS payload कॉन्फ़िगर करें, चल रहा संस्करण सत्यापित करें, और सुरक्षित कॉन्फ़िग माइग्रेशन लागू करें।",
