"power_wake_setup_cta": "जगाना और साइन-इन सेट करें",
"power_wake_offer_hint": "ps5upload यह आपके लिए सेट कर सकता है — यह ज़रूरी जानकारी कंसोल से पढ़ लेता है। कुछ ढूँढना नहीं, और कोई दूसरा ऐप नहीं चाहिए।",
"power_wake_working": "यह कंसोल सेट हो रहा है…",
"power_wake_working_detail": "रिमोट प्ले चालू किया जा रहा है, कंसोल से आपका खाता पढ़ा जा रहा है और रजिस्टर किया जा रहा है। आपको कुछ नहीं करना है।",
"power_wake_needs_awake": "इसे सेट करने के लिए कंसोल चालू करें — पेयरिंग नेटवर्क पर रजिस्टर होती है, इसलिए यह केवल कंसोल के जागे रहने पर काम करती है। आपको यह केवल एक बार करना है।",
"power_wake_ready_userselect": "जगाना सेट हो गया — यह उपयोगकर्ता-चयन स्क्रीन पर रुकता है",
