"power_telemetry_note_unsupported_firmware": "इस कंसोल का फ़र्मवेयर ICC स्वास्थ्य काउंटर उपलब्ध नहीं कराता, इसलिए पढ़ने को कुछ नहीं है। कंसोल या ps5upload में कोई गड़बड़ी नहीं है।",
