"beta_features_hint": "साइडबार में निर्माणाधीन स्क्रीन जोड़ता है। ये काम करती हैं लेकिन अभी भरोसेमंद नहीं हैं, और बदल सकती हैं या हटाई जा सकती हैं। अभी इससे FPKG बिल्डर (FPKG में बदलें) दिखता है।",
"bug_report_open_github": "GitHub इश्यू खोलें",
"bug_report_post_hint_v2": "अब इसे वहाँ भेजें जहाँ इसे देखा जाएगा: GitHub पर एक इश्यू खोलें और .zip संलग्न करें, या इसे Discord के बग-रिपोर्ट चैनल में पोस्ट करें। जिसे ठीक होने तक ट्रैक करना हो उसके लिए GitHub बेहतर है; अगर आप बस पूछना चाहते हैं कि क्या यह ज्ञात समस्या है तो Discord तेज़ है। दोनों ही स्थितियों में संक्षेप में बताएँ कि आप क्या कर रहे थे।",
