"profile.accountId.confirm_replace": "स्लॉट {slot} में पहले से खाता आईडी {old} है।\n\nइसे {next} में बदलने से {old} के तहत बने सेव इस प्रोफ़ाइल के नहीं माने जाएँगे। वे हटाए नहीं जाते — {old} वापस करने से पहुँच लौट आती है।\n\nआगे बढ़ने से पहले इसे लिख लें। खाता आईडी बदलें?",
"profile.accountId.confirm_set": "स्लॉट {slot} की खाता आईडी {next} पर सेट करें?\n\nइससे ऑफ़लाइन खाता सक्रिय होता है। अब से बने सेव इस आईडी से जुड़े रहेंगे — अगर आप इसे बाद में बदलते हैं, तो वापस सेट करने तक वे पहचाने नहीं जाएँगे।",
"pkglib.url.title": "HTTP(S) लिंक से इंस्टॉल करें",
"pkglib.url.help": "यह कंप्यूटर पैकेज को एक साथ कई कनेक्शनों पर डाउनलोड करता है और आपके नेटवर्क पर PS5 को देता है, इसलिए ट्रांसफ़र कंसोल की धीमी एकल स्ट्रीम के बजाय आपकी लाइन की गति से चलता है। किसी भी मशीन पर कुछ स्टोर नहीं होता, इसलिए 100 GB के गेम के लिए भी खाली जगह नहीं चाहिए। लिंक बाइट रेंज सपोर्ट करने वाला सीधा डाउनलोड होना चाहिए। इंस्टॉल पूरा होने तक इस कंप्यूटर को जागा रखें।",
"pkglib.url.label": "सीधा पैकेज URL",
"pkglib.url.install": "लिंक इंस्टॉल करें",
"pkglib.url.confirmTitle": "प्रायोगिक लिंक इंस्टॉल शुरू करें?",
"pkglib.url.confirmBody": "यह कंप्यूटर लिंक से पैकेज डाउनलोड करके PS5 को देता है, इसलिए इंस्टॉल पूरा होने तक इसे जागा और जुड़ा रहना चाहिए। मौजूदा टाइटल के ऊपर दोबारा इंस्टॉल करने से, Sony का इंस्टॉलर विफल होने पर, वह हट सकता है। केवल ऐसे भरोसेमंद पैकेज URL का उपयोग करें जिसे इंस्टॉल करने की आपको अनुमति हो।",
