"fs_replace_dialog_title": "“{name}” को बदलने के लिए फ़ाइल चुनें",
"fs_replace_confirm_title": "यह फ़ाइल बदलें?",
"fs_replace_confirm_body": "“{name}” ओवरराइट हो जाएगी और पुरानी सामग्री हमेशा के लिए चली जाएगी। अगर यह माउंट की गई गेम इमेज के अंदर है, तो गलत फ़ाइल से गेम बूट होना रुक सकता है।",
